return {
	package = {
		authors = {"Stephen Leitnick"},
		description = "Signal class",
		exclude = {"node_modules", "package.json", "**/*.ts"},
		license = "MIT",
		name = "sleitnick/signal",
		realm = "shared",
		registry = "https://github.com/UpliftGames/wally-index",
		version = "2.0.3",
	},
}

local CashLabelController = {}

type UIController = {
	OpenGui: (guiName: string) -> nil;
	CloseGui: (guiName: string) -> nil;
}

local ReplicatedStorage = game:GetService("ReplicatedStorage")

local SharedUtil = require(ReplicatedStorage.Shared.Modules.SharedUtils)
local PlotClient = require(ReplicatedStorage.Shared.Classes.PlotClient)

local client = game.Players.LocalPlayer
local HUD: typeof(game.StarterGui.HUD) = client:WaitForChild("PlayerGui"):WaitForChild("HUD")
local UIController: UIController?
local plot: PlotClient

local function teleportPlayer(part: Part)
	client.Character:PivotTo(part.CFrame)
end

function CashLabelController.init(_UIController: UIController)
	UIController = _UIController
	plot = PlotClient.getPlotObject(client)
	local plotModel = plot.MODEL :: typeof(workspace.Map.Plots.PlotTemplate)

	HUD.Right.GardenTeleport.Activated:Connect(function()
		teleportPlayer(plotModel.Teleports.GardenTeleport)
	end)
	HUD.Right.SeedsTeleport.Activated:Connect(function()
		teleportPlayer(plotModel.Teleports.SeedShopTeleport)
	end)
	HUD.Right.SellTeleport.Activated:Connect(function()
		teleportPlayer(plotModel.Teleports.SellTeleport)
	end)
end

return CashLabelController

